def parse_amount(text):
    """Сумма из строки письма поставщика: Decimal с двумя знаками или None."""
    if not isinstance(text, str):
        raise TypeError("text must be a str")
    s = text.strip(" \u00a0\t\n\r\f\v")
    if s in NO_AMOUNT:
        return None
    for mark in CURRENCY_MARKS:
        if s.endswith(mark):
            s = s[: -len(mark)].rstrip(GROUP_SPACES)
            break
    if not s:
        raise ValueError("currency mark without number")
    negative = False
    if s.startswith("-"):
        negative = True
        s = s[1:]
    if not s:
        raise ValueError("minus without number")
    if s[0] in GROUP_SPACES:
        raise ValueError("space between minus and number")
    if "," in s and "." in s:
        raise ValueError("both comma and dot")
    sep = None
    if "," in s:
        sep = ","
    elif "." in s:
        sep = "."
    if sep is not None:
        int_part, frac_part = s.split(sep)
        if not frac_part or len(frac_part) > 2 or not frac_part.isdigit():
            raise ValueError("bad fractional part")
    else:
        int_part = s
        frac_part = ""
    if not int_part:
        raise ValueError("missing integer part")
    groups = []
    current = []
    for ch in int_part:
        if ch in GROUP_SPACES:
            groups.append("".join(current))
            current = []
        elif ch.isdigit() and ch.isascii():
            current.append(ch)
        else:
            raise ValueError("bad character")
    groups.append("".join(current))
    if any(g == "" for g in groups):
        raise ValueError("bad grouping")
    if len(groups) > 1:
        if not (1 <= len(groups[0]) <= 3):
            raise ValueError("bad first group")
        for g in groups[1:]:
            if len(g) != 3:
                raise ValueError("bad group size")
    digits = "".join(groups)
    if frac_part:
        value = Decimal(digits + "." + frac_part)
    else:
        value = Decimal(digits)
    value = value.quantize(Decimal("0.01"))
    if negative:
        value = -value
    return value
